python3 - <<'PY'
from pathlib import Path
idx = Path('web/index.html').read_text()
js = Path('web/viewer.js').read_text()
bad = []
for label, text in [('index', idx), ('viewer', js)]:
    # Allow 'original points' and SQUISH/compare notes about original points
    import re
    # Strip those allowed phrases then look for leftover 'the original' / gray original
    cleaned = re.sub(r'original points', 'ORIG_POINTS', text)
    cleaned = re.sub(r'original trajectory\.', 'ORIG_TRAJ.', cleaned)  # original points tip
    if 'the original' in cleaned or 'gray original' in cleaned or 'from the original' in cleaned or 'match the original' in cleaned:
        for i, line in enumerate(cleaned.splitlines(), 1):
            if any(p in line for p in ['the original', 'gray original', 'from the original', 'match the original']):
                # skip comment/code-only if needed
                if 'original points' in text.splitlines()[i-1] if False else True:
                    if 'ORIG_POINTS' in line or 'ORIG_TRAJ' in line:
                        continue
                    bad.append(f'{label}:{i}: {line.strip()[:120]}')
print('BAD' if bad else 'LIVE_OK')
for b in bad[:20]:
    print(b)
# positive checks
need = [
    'match the Gray path',
    'from the Gray path',
    'shorter than the Gray path',
    'full input trajectory shown in gray',
    'percent of original points',
    'Grid spacing (δ)',
]
for n in need:
    if n not in idx and n not in js:
        print('MISSING', n)
    else:
        print('HAS', n)
